const menuButton=document.querySelector(".menu-toggle"),navigation=document.querySelector("nav");function closeMenu(){navigation.classList.remove("open"),menuButton.setAttribute("aria-expanded","false")}menuButton.addEventListener("click",()=>{const isOpen=navigation.classList.toggle("open");menuButton.setAttribute("aria-expanded",String(isOpen))}),navigation.querySelectorAll("a").forEach(link=>{link.addEventListener("click",closeMenu)});const shareUrl=encodeURIComponent(window.location.href),facebookLink=document.querySelector(".share-facebook"),linkedInLink=document.querySelector(".share-linkedin"),nativeShareButton=document.querySelector(".share-native");facebookLink.href=`https://www.facebook.com/sharer/sharer.php?u=${shareUrl}`,linkedInLink.href=`https://www.linkedin.com/sharing/share-offsite/?url=${shareUrl}`,nativeShareButton.addEventListener("click",async()=>{if(navigator.share){await navigator.share({title:"Urban Coffee Novi Sad",url:window.location.href});return}await navigator.clipboard.writeText(window.location.href)});